import { VoltAgent, createWorkflowChain, addAgent } from '@voltagent/core';
import { honoServer } from '@voltagent/server-hono';
import { openai } from '@ai-sdk/openai';
import { z } from 'zod';

// Define the schema for the extracted payload
const PayloadSchema = z.object({
  title: z.string(),
  description: z.string(),
  metadata: z.object({
    category: z.string(),
    priority: z.string().optional(),
    tags: z.array(z.string()).optional(),
  }),
});

// Create the VoltAgent instance with OpenAI provider
const voltAgent = new VoltAgent({
  provider: openai,
  apiKey: process.env.OPENAI_API_KEY,
});

// Define the receiver agent - extracts structured JSON from incoming text
const receiver = addAgent(voltAgent, {
  id: 'receiver',
  name: 'Receiver Agent',
  model: 'gpt-4o-mini',
  systemPrompt: 'You are a data extraction specialist. Extract structured information from incoming text and return it as JSON.',
  outputSchema: PayloadSchema,
});

// Define the processor agent - analyzes the extracted payload and generates a summary
const processor = addAgent(voltAgent, {
  id: 'processor',
  name: 'Processor Agent',
  model: 'gpt-4o-mini',
  systemPrompt: 'You are a data analysis specialist. Analyze the provided JSON payload and generate a comprehensive summary.',
  outputSchema: z.object({
    summary: z.string(),
    insights: z.array(z.string()),
    recommendations: z.array(z.string()).optional(),
  }),
});

// Create a workflow chain that connects receiver to processor
const workflow = createWorkflowChain(voltAgent, {
  id: 'process-workflow',
  agents: [receiver, processor],
});

// Set up the Hono server
const app = honoServer(voltAgent, {
  port: 3000,
});

// Register the workflow with the server
app.registerWorkflow(workflow);

// Expose the /api/process endpoint that triggers the workflow
app.post('/api/process', async (c) => {
  try {
    const { text } = await c.req.json();

    if (!text) {
      return c.json({ error: 'Missing required field: text' }, 400);
    }

    // Execute the workflow
    const result = await workflow.execute({ input: text });

    return c.json({
      success: true,
      result,
    });
  } catch (error) {
    console.error('Error processing request:', error);
    return c.json(
      { error: 'Failed to process request', details: error instanceof Error ? error.message : 'Unknown error' },
      500
    );
  }
});

// Start the server
console.log('Starting VoltAgent A2A Protocol Server on port 3000...');
console.log('Endpoint: http://localhost:3000/api/process');

export default app;

